package com.pratik.imagetap;
import android.content.Context;import android.graphics.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Versioned, bounded preset format. Staged validation precedes an atomic slot-pointer swap. */
final class PresetArchive {
 static final long MAX_ENTRY=32L*1024*1024,MAX_TOTAL=256L*1024*1024;static final int MAX_IMAGES=500,MAX_MANIFEST=1024*1024;
 static final class Staged implements AutoCloseable {final File folder;final String name;final ActionType action;final List<TargetOptions> options;boolean committed;Staged(File f,String n,List<TargetOptions> o,ActionType a){folder=f;name=n;options=o;action=a;}int count(){return options.size();}public void close(){if(!committed)PresetStore.delete(folder);}}
 static String entryName(int i){return "images/"+fileName(i);}static String fileName(int i){return String.format(Locale.ROOT,"%04d.png",i);}
 static void exportSlot(Context c,int slot,OutputStream output)throws IOException{
  PresetStore.check(slot);List<File> files=PresetStore.files(PresetStore.folder(c,slot));if(files.size()>MAX_IMAGES)throw new IOException("Preset exceeds 500 images");String name=PresetStore.name(c,slot).trim();if(name.isEmpty()||name.length()>200)throw new IOException("Use a preset name of 1–200 characters");
  try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(output))){JSONObject manifest=new JSONObject();manifest.put("format","autobash-preset");manifest.put("version",2);manifest.put("action",ActionType.selected(c).id);manifest.put("name",name);JSONArray images=new JSONArray();
   for(int i=0;i<files.size();i++){TargetOptions o=TargetOptions.load(c,files.get(i));if(o.name.length()>1000)throw new IOException("Target name exceeds 1000 characters");JSONObject item=new JSONObject();item.put("file",entryName(i));item.put("enabled",o.enabled);item.put("sourceWidth",o.sourceWidth);item.put("name",o.name);if(o.area!=null){JSONObject a=new JSONObject();a.put("left",o.area.left);a.put("top",o.area.top);a.put("right",o.area.right);a.put("bottom",o.area.bottom);item.put("area",a);}images.put(item);}manifest.put("images",images);byte[] metadata=manifest.toString().getBytes(StandardCharsets.UTF_8);if(metadata.length>MAX_MANIFEST)throw new IOException("Preset metadata is too large");zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(metadata);zip.closeEntry();
   long total=metadata.length;byte[] buffer=new byte[32768];for(int i=0;i<files.size();i++){File f=files.get(i);validatePng(f);zip.putNextEntry(new ZipEntry(entryName(i)));try(InputStream in=new FileInputStream(f)){int n;long size=0;while((n=in.read(buffer))!=-1){size+=n;total+=n;if(size>MAX_ENTRY||total>MAX_TOTAL)throw new IOException("Preset exceeds sharing size limit");zip.write(buffer,0,n);}}zip.closeEntry();}
  }catch(JSONException e){throw new IOException("Could not encode preset",e);}
 }
 static Staged stage(Context c,InputStream input)throws IOException{
  if(input==null)throw new IOException("Cannot open preset file");File folder=new File(c.getFilesDir(),"preset-import-"+UUID.randomUUID());if(!folder.mkdirs())throw new IOException("Cannot prepare import");boolean valid=false;
  try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){Set<String> entries=new HashSet<>();byte[] metadata=null,buffer=new byte[32768];long total=0;ZipEntry entry;
   while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(entry.isDirectory()||(!name.equals("manifest.json")&&!name.matches("images/[0-9]{4}\\.png")))throw new IOException("Unexpected file in preset");if(!entries.add(name)||entries.size()>MAX_IMAGES+1)throw new IOException("Repeated files or too many images");boolean manifest=name.equals("manifest.json");long limit=manifest?MAX_MANIFEST:MAX_ENTRY;ByteArrayOutputStream json=manifest?new ByteArrayOutputStream():null;
    try(OutputStream out=manifest?json:new FileOutputStream(new File(folder,name.substring(7)))){int n;long length=0;while((n=zip.read(buffer))!=-1){length+=n;total+=n;if(length>limit||total>MAX_TOTAL)throw new IOException("Preset exceeds sharing size limit");out.write(buffer,0,n);}}if(manifest)metadata=json.toByteArray();zip.closeEntry();}
   if(metadata==null)throw new IOException("Missing preset manifest");JSONObject manifest=new JSONObject(new String(metadata,StandardCharsets.UTF_8));if(!"autobash-preset".equals(manifest.getString("format"))||(manifest.getInt("version")!=1&&manifest.getInt("version")!=2))throw new IOException("Unsupported preset format");String actionId=manifest.getInt("version")==1?"tap":manifest.getString("action");ActionType action=ActionType.parse(actionId);if(!action.id.equals(actionId))throw new IOException("Unsupported preset action");String name=manifest.getString("name").trim();if(name.isEmpty()||name.length()>200)throw new IOException("Invalid preset name");JSONArray images=manifest.getJSONArray("images");if(images.length()>MAX_IMAGES||entries.size()!=images.length()+1)throw new IOException("Preset image count does not match");
   List<TargetOptions> options=new ArrayList<>();for(int i=0;i<images.length();i++){JSONObject item=images.getJSONObject(i);if(!entryName(i).equals(item.getString("file"))||!entries.contains(entryName(i)))throw new IOException("Missing or invalid image reference");String label=item.getString("name");if(label.length()>1000)throw new IOException("Target name is too long");RegionRules.Region area=null;if(item.has("area")){JSONObject a=item.getJSONObject("area");double l=a.getDouble("left"),t=a.getDouble("top"),r=a.getDouble("right"),b=a.getDouble("bottom");if(!Double.isFinite(l)||!Double.isFinite(t)||!Double.isFinite(r)||!Double.isFinite(b)||l<0||t<0||r>1||b>1||l>=r||t>=b)throw new IOException("Invalid target search area");area=new RegionRules.Region((float)l,(float)t,(float)r,(float)b,75);}options.add(new TargetOptions(item.getBoolean("enabled"),item.getInt("sourceWidth"),area,label));validatePng(new File(folder,fileName(i)));}
   valid=true;return new Staged(folder,name,options,action);
  }catch(JSONException|IllegalArgumentException e){throw new IOException("Invalid AutoBash preset: "+e.getMessage(),e);}finally{if(!valid)PresetStore.delete(folder);}
 }
 static void validatePng(File f)throws IOException{
  if(f.length()>MAX_ENTRY)throw new IOException("Image exceeds 32 MiB");try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(f)))){byte[] header=new byte[8];in.readFully(header);if(!Arrays.equals(header,new byte[]{(byte)137,80,78,71,13,10,26,10}))throw new IOException("Invalid PNG image");boolean first=true,hasData=false;byte[] buffer=new byte[32768];while(true){int length=in.readInt();if(length<0||length>MAX_ENTRY)throw new IOException("Invalid PNG chunk");byte[] type=new byte[4];in.readFully(type);String kind=new String(type,StandardCharsets.US_ASCII);if(first&&(!kind.equals("IHDR")||length!=13))throw new IOException("Invalid PNG header");first=false;CRC32 crc=new CRC32();crc.update(type);int remaining=length;while(remaining>0){int n=Math.min(buffer.length,remaining);in.readFully(buffer,0,n);crc.update(buffer,0,n);remaining-=n;}if((int)crc.getValue()!=in.readInt())throw new IOException("PNG data is damaged");if(kind.equals("IDAT"))hasData=true;if(kind.equals("IEND")){if(length!=0||!hasData||in.read()!=-1)throw new IOException("Incomplete PNG image");break;}}}
  BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),bounds);if(bounds.outWidth<1||bounds.outHeight<1||(long)bounds.outWidth*bounds.outHeight>20000000)throw new IOException("Invalid or oversized image");Bitmap b=BitmapFactory.decodeFile(f.getPath());if(b==null)throw new IOException("Unreadable PNG image");b.recycle();
 }
 static synchronized void install(Context c,Staged staged,int slot,String expectedFolder)throws IOException{
  if(ActionType.selected(c)!=staged.action)throw new IOException("Choose the "+staged.action.label+" collection for this preset");PresetStore.check(slot);File previous=PresetStore.folder(c,slot);if(staged.committed||!staged.folder.isDirectory())throw new IOException("Import is no longer available");if(!previous.getName().equals(expectedFolder))throw new IOException("That preset changed. Choose the slot again.");android.content.SharedPreferences opts=c.getSharedPreferences("target-options",0);
  try{for(int i=0;i<staged.count();i++){File f=new File(staged.folder,fileName(i));try(FileOutputStream out=new FileOutputStream(f,true)){out.getFD().sync();}staged.options.get(i).save(c,f);}if(!PresetStore.prefs(c).edit().putString("dir"+slot,staged.folder.getName()).putString("name"+slot,staged.name).putInt("active",slot).commit())throw new IOException("Could not commit imported preset");staged.committed=true;
  }catch(RuntimeException e){throw new IOException("Could not save imported options",e);}finally{if(!staged.committed){android.content.SharedPreferences.Editor e=opts.edit();for(int i=0;i<staged.count();i++)e.remove(TargetOptions.key(new File(staged.folder,fileName(i))));e.commit();}}
  boolean used=false;for(int i=0;i<PresetStore.COUNT;i++)if(PresetStore.folder(c,i).equals(previous))used=true;if(!used)PresetStore.delete(previous);
 }
}
